const raw = $input.first().json;
const body = raw.body ?? raw;

const to = String(body.to || body.reviewer_email || 'erik@igisnext.com').trim();
const reviewUrl = String(body.review_url || '').trim();

if (!reviewUrl) {
  throw new Error('Missing review_url in webhook payload');
}

const headline = String(body.headline || 'Artikel review').trim();
const resubmitted = body.resubmitted === true || body.resubmitted === 'true';
const openReviewLabel = String(body.open_review_label || 'Open review').trim();

let preview = String(body.mail_preview || body.content_preview || '').trim();
if (!preview) {
  const fallback = String(body.content || body.content_human || '').trim();
  const words = fallback.split(/\s+/).filter(Boolean);
  preview = words.length <= 40
    ? fallback
    : `${words.slice(0, 40).join(' ')}…`;
}

const escapeHtml = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const previewHtml = escapeHtml(preview).replace(/\n/g, '<br>');

const emailHtml = `<!DOCTYPE html>
<html>
<body style="margin:0;padding:0;background:#eae6dc;font-family:Figtree,Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0" style="background:#eae6dc;padding:40px 16px;">
<tr><td align="center">
<table width="640" cellpadding="0" cellspacing="0" style="max-width:640px;background:#ffffff;border-radius:20px;padding:32px 36px;color:#2e2014;">
<tr><td>
<p style="margin:0 0 8px;font-size:14px;color:#ada695;">Content Engine · Review${resubmitted ? ' · Herzien' : ''}</p>
<h1 style="margin:0 0 24px;font-size:28px;line-height:1.25;color:#033dff;">${escapeHtml(headline)}</h1>
<p style="margin:0 0 28px;font-size:14px;line-height:1.6;">${previewHtml || '<em>Geen preview beschikbaar</em>'}</p>
<p style="margin:0;"><a href="${escapeHtml(reviewUrl)}" style="display:inline-block;background:#52ffa8;color:#033dff;text-decoration:none;font-weight:600;font-size:14px;padding:12px 28px;border-radius:20px;">${escapeHtml(openReviewLabel)}</a></p>
</td></tr>
</table>
</td></tr>
</table>
</body>
</html>`;

return {
  json: {
    to,
    review_url: reviewUrl,
    headline,
    mail_preview: preview,
    article_id: body.article_id,
    slot_id: body.slot_id,
    subject: resubmitted ? `Review (herzien): ${headline}` : `Review: ${headline}`,
    email_html: emailHtml,
  },
};
